public class ServiceWorker implements java.io.Serializable {
    private static final long serialVersionUID = 1L;

    // Prevents sensitive or un-serializable state from leaking to storage
    private final transient String connectionToken;

    // Ensures cross-thread visibility without heavy monitor locks
    private volatile boolean shutdownRequested = false;

    public ServiceWorker(String connectionToken) {
        this.connectionToken = connectionToken;
    }

    public void run() {
        while (!shutdownRequested) {
            // Perform task execution loop
        }
    }

    public void shutdown() {
        this.shutdownRequested = true;
    }
}
